// ============================================================
// Extract and validate delivery payload
// ============================================================
const body = $input.first().json.body || $input.first().json;
const project_id = (body.project_id || '').trim();
const action = (body.action || 'approve').trim().toLowerCase();
const script_ids = body.script_ids || [];
const notes = (body.notes || '').trim();

if (!project_id) throw new Error('project_id is required');
if (!['approve', 'reject'].includes(action)) {
  throw new Error('action must be approve or reject');
}

return [{ json: { project_id, action, script_ids, notes } }];

// Merge project + scripts + payload
const payload = $('Extract Delivery Payload').first().json;
const project = $('Fetch Project').first().json;
const scripts = $input.all().map(item => item.json);

return [{ json: {
  ...payload,
  project,
  scripts,
  script_count: scripts.length
} }];

// Match generated scripts to existing Google Docs by UGC_C{N} pattern
const data = $('Format Approved Scripts').first().json;
const docs = ($input.first().json.files || []).sort((a, b) => {
  const nA = parseInt((a.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  const nB = parseInt((b.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  return nA - nB;
});

const items = data.scripts.map((s, i) => ({
  json: {
    doc_id: docs[i] ? docs[i].id : null,
    doc_name: docs[i] ? docs[i].name : null,
    doc_content: s.doc_content,
    script_number: s.script_number
  }
}));

return items.length ? items : [{ json: { _skip: true } }];

// Prepare for ClickUp lookup after doc loop completes
const data = $('Format Approved Scripts').first().json;
return [{ json: data }];

// Find the brand's folder and extract the pipeline list ID
const folders = ($input.first().json.folders || []);
const data = $('Format Approved Scripts').first().json;
const target = data.brand_name + ' - UGC';
const folder = folders.find(f => f.name === target) || folders.find(f => f.name.toLowerCase().includes(data.brand_name.toLowerCase()));
if (!folder) return [{ json: { list_id: null } }];
const list = (folder.lists || []).find(l => l.name.includes('Pipeline')) || (folder.lists || [])[0];
return [{ json: { list_id: list ? list.id : null, folder_id: folder.id } }];

// Match scripts to UGC_C{N} ClickUp tasks
const tasks = ($input.first().json.tasks || []).filter(t => /^UGC_C\d+/.test(t.name)).sort((a, b) => {
  const nA = parseInt((a.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  const nB = parseInt((b.name.match(/UGC_C(\d+)/) || [0,0])[1]);
  return nA - nB;
});
const scripts = $('Format Approved Scripts').first().json.scripts;
const items = scripts.map((s, i) => {
  const task = tasks[i];
  if (!task) return null;
  return { json: {
    task_id: task.id,
    description: `CONCEPT: ${s.concept_name}\nFORMAT: ${s.format}\nDURATION: ${s.estimated_duration}\n\n== FULL SCRIPT ==\n${s.full_script}\n\n== HOOK ==\n${s.hook}\n\n---\nAI-generated by Smashed Agency UGC Script Agent Team\nDelivered to client`
  }};
}).filter(Boolean);
return items.length ? items : [{ json: { _skip: true } }];

// ============================================================
// Update script records in Airtable to 'Delivered'
// ============================================================
const data = $('Format Approved Scripts').first().json;
const items = data.script_ids.map(id => ({ json: {
  record_id: id,
  pm_status: 'Approved',
  overall_status: 'Delivered'
}}));
return items.length ? items : [{ json: { _skip: true } }];

const data = $('Format Approved Scripts').first().json;
const summary = data.scripts.map(s => `  ${s.script_number}. "${s.concept_name}" (${s.format}) — "${(s.hook || '').substring(0, 50)}..."`).join('\n');
return [{ json: {
  brand_name: data.brand_name,
  client_code: data.client_code,
  client_name: data.client_name,
  total_scripts: data.total_scripts,
  script_summary: summary,
  project_id: data.project_id
} }];

